// Pure todo logic, shared by index.html and check/.
// Ordering rule (project decision): completed todos always sit below all
// active todos; within each group, insertion order (oldest first) is kept.
(function (root) {
  var FILTERS = ['all', 'active', 'completed'];

  function visibleTodos(todos, filter) {
    var active = todos.filter(function (t) { return !t.completed; });
    var done = todos.filter(function (t) { return !!t.completed; });
    if (filter === 'active') return active;
    if (filter === 'completed') return done;
    return active.concat(done);
  }

  var api = { FILTERS: FILTERS, visibleTodos: visibleTodos };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.TodoLogic = api;
})(this);

